package mz.bam.seeky.android;
import java.net.*;import java.security.*;import java.util.*;import java.nio.charset.StandardCharsets;
final class CloudProtocol {
 static final int CHUNK=8*1024*1024;static final long MAX=536870912;
 static String random(){byte[] b=new byte[32];new SecureRandom().nextBytes(b);return Base64.getUrlEncoder().withoutPadding().encodeToString(b);}
 static String challenge(String verifier){try{return Base64.getUrlEncoder().withoutPadding().encodeToString(MessageDigest.getInstance("SHA-256").digest(verifier.getBytes(StandardCharsets.US_ASCII)));}catch(Exception e){throw new IllegalStateException(e);}}
 static String base(String value){try{URI u=new URI(value.trim());if(!u.getScheme().equals("https")||u.getHost()==null||!u.getHost().matches("[a-z0-9-]+\\.supabase\\.co")||u.getUserInfo()!=null||u.getPort()!=-1||u.getQuery()!=null||u.getFragment()!=null||!(u.getPath().isEmpty()||u.getPath().equals("/")))throw new IllegalArgumentException();return "https://"+u.getHost();}catch(Exception e){throw new IllegalArgumentException("Use a URL HTTPS do projecto Supabase.");}}
 static String enc(String value){try{return URLEncoder.encode(value,"UTF-8");}catch(Exception e){throw new IllegalStateException(e);}}
 static String authorize(String base,String key,String provider,String verifier,String state){if(!provider.equals("google")&&!provider.equals("facebook"))throw new IllegalArgumentException("Provedor inválido.");String redirect="seekyestudos://auth/callback?state="+enc(state);return base(base)+"/auth/v1/authorize?provider="+provider+"&redirect_to="+enc(redirect)+"&code_challenge="+challenge(verifier)+"&code_challenge_method=s256&apikey="+enc(key);}
 static String callback(String value,String expected,long started,long now){try{URI u=new URI(value);if(!"seekyestudos".equals(u.getScheme())||!"auth".equals(u.getHost())||!"/callback".equals(u.getPath())||u.getUserInfo()!=null||u.getPort()!=-1||u.getFragment()!=null||now<started||now-started>600000||expected.isEmpty())throw new IllegalArgumentException();Map<String,String> p=new HashMap<>();for(String pair:u.getRawQuery().split("&")){String[] parts=pair.split("=",2);String k=URLDecoder.decode(parts[0],"UTF-8"),v=parts.length>1?URLDecoder.decode(parts[1],"UTF-8"):"";if(p.put(k,v)!=null)throw new IllegalArgumentException();}if(!MessageDigest.isEqual(expected.getBytes(StandardCharsets.UTF_8),p.getOrDefault("state","").getBytes(StandardCharsets.UTF_8)))throw new IllegalArgumentException();if(p.containsKey("error"))throw new IllegalStateException("Autorização recusada. Pode tentar novamente.");String code=p.get("code");if(code==null||code.isEmpty()||code.length()>4096)throw new IllegalArgumentException();return code;}catch(IllegalStateException e){throw e;}catch(Exception e){throw new IllegalArgumentException("Este retorno de login expirou ou não pertence à sessão iniciada.");}}
 static String object(String uid,String id,int chunk){if(!uid.matches("[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}")||!id.matches("[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}")||chunk<0||chunk>=64)throw new IllegalArgumentException("Caminho inválido.");return uid+"/"+id+"/"+String.format(Locale.ROOT,"%05d.bin",chunk);}
 static boolean canPublish(String owner,String uid,long known,long actual){return (owner.isEmpty()||owner.equals(uid))&&known==actual;}
}
